export class TypeStore {
  parent: KitStore
  private rType: RxType                  // RMap storage
  private rAttributes: RxAttributes
  private rAuthors: RxAuthorUuids       // RArray of author guids
  private rModels: RxModels             // RArray of 3D models
  private rConnectors: RxConnectors     // RArray of connectors

  public models: Map<string, ModelStore>
  public connectors: Map<string, ConnectorStore>

  // Properties: guid, name, parent, isAbstract, stock, unit, icon, etc.

  snapshot(): Type {
    return {
      guid, name, parent, isAbstract, stock, unit, icon, image, description,
      authors: storeArray.map(store => ({ guid: store.guid })),
      attributes: Array.from(attributes.values()).map(a => a.snapshot()),
      models: Array.from(models.values()).map(m => m.snapshot()),
      connectors: Array.from(connectors.values()).map(c => c.snapshot())
    }
  }

  change(diff: TypeDiff) {
    this.parent.rDoc.transact(() => {
      if (diff.name !== undefined) this.rType.set("name", diff.name)
      if (diff.authors !== undefined) {
        this.rAuthors.delete(0, this.rAuthors.length)
        diff.authors.forEach(author => this.rAuthors.push([author.guid]))
      }
      if (diff.models) {
        if (diff.models.added) diff.models.added.forEach(m => this.createModel(m))
        if (diff.models.removed) this.deleteModel(id)
        if (diff.models.updated) this.updateModel(id, diff)
      }
    })
  }
}
