  private pieces: Map<string, PieceStore>
  private connections: Map<string, ConnectionStore>
  private stats: Map<string, StatStore>      // Quality metrics
  private layers: Map<string, LayerStore>
  private groups: Map<string, GroupStore>
  private location?: RxLocationStore

  // Caching strategy
  private _piecesCache?: Piece[]
  private _piecesVersion = 0
  private _connectionsCache?: Connection[]
  private _connectionsVersion = 0

  markDirty() {
    this.dirty = true
    this.parent.markDirty()             // Cascade upward
  }

  snapshot(): Design {
    if (!this.dirty && this.cache) return this.cache  // Fast path

    const currentData = {
      pieces: Array.from(this.pieces.values()).map(p => p.snapshot()),
      connections: Array.from(this.connections.values()).map(c => c.snapshot()),
      stats, props, layers, activeLayer, groups, location, authors, concepts
    }
    this.cache = currentData
    this.dirty = false
    return this.cache
  }

  // Optimized snapshot methods
  snapshotPieces(): Piece[] {
    const currentVersion = (this.rPieces as any)._clock
    if (this._piecesCache && this._piecesVersion === currentVersion) {
      return this._piecesCache   // Return cached if no changes
    }
    this._piecesCache = Array.from(this.pieces.values()).map(p => p.snapshot())
    this._piecesVersion = currentVersion
    return this._piecesCache
  }
}
