### **5. SNAPSHOT BUILDING PATTERN**

**snapshot() → converts RMap back to domain object:**

```typescript
// TypeStore.snapshot()
snapshot(): Type {
  const currentData = {
    guid: this.guid,                          // Read from rType['guid']
    name: this.name,                          // Read from rType['name']
    parent: this.parentGuid ? { guid: this.parentGuid } : undefined,
    connectors: Array.from(this.connectors.values())
      .map(connectorStore => connectorStore.snapshot()),  // Recursive!
    attributes: Array.from(this.attributes.values())
      .map(attrStore => attrStore.snapshot())
  }

  const currentHash = this.hash(currentData)
  if (!this.cache || this.cacheHash !== currentHash) {
    this.cache = currentData
    this.cacheHash = currentHash
  }
  return this.cache
}

// Avoids rebuilding if nothing changed (hash comparison)
