### **6. CHANGE/DIFF APPLICATION PATTERN**

**How diffs are applied to update RMaps:**

```typescript
// DesignStore.change(diff: DesignDiff)
change(diff: DesignDiff) {
  this.dirty = true          // Mark as needing rebuild

  if (diff.pieces !== undefined) {
    if (typeof diff.pieces === "object" && !Array.isArray(diff.pieces)) {
      // It's a differential update
      if (diff.pieces.added) {
        diff.pieces.added.forEach(piece => this.createPiece(piece))
      }
      if (diff.pieces.updated) {
        diff.pieces.updated.forEach(({ piece, diff: pieceDiff }) => {
          const pieceStore = this.pieces.get(piece.guid)
          if (pieceStore) {
            pieceStore.change(pieceDiff)        // Cascade downward
          }
        })
      }
      if (diff.pieces.removed) {
        diff.pieces.removed.forEach(pieceId => {
          const index = Array.from(this.pieces.values())
            .findIndex(p => p.guid === pieceId.guid)
          if (index !== -1) {
            this.pieces.delete(pieceId.guid)
            this.rPieces.delete(index, 1)       // Delete from RArray
          }
        })
      }
    }
  }

  this.cache = undefined                       // Invalidate cache
  this.cacheHash = undefined
}
```

