### **7. OBSERVER/SUBSCRIPTION SYSTEM**

**Watch for RMap changes:**

```typescript
// Store.onFieldChanged(key, subscribe)
onFieldChanged(key: string, subscribe: Subscribe) {
  const subscriberCallback = () => {
    subscribe(() => { })                       // Notify subscriber
  }

  if (!this.fieldSubscribers.has(key)) {
    this.fieldSubscribers.set(key, new Set())

    // Set up deep observer on this specific field
    const fieldObserver = createFieldObserver(
      this.rMap,
      key,
      (callback) => {
        const subscribers = this.fieldSubscribers.get(key)
        subscribers?.forEach(cb => cb())
        callback()
        return () => {}
      },
      deep  // Shallow vs deep changes
    )
    this.fieldObservers.set(key, fieldObserver)
  }

  const subscribers = this.fieldSubscribers.get(key)!
  subscribers.add(subscriberCallback)

  // Return unsubscribe function
  return () => {
    subscribers.delete(subscriberCallback)
    if (subscribers.size === 0) {
      // Clean up the field observer if no more subscribers
      this.fieldObservers.get(key)?.()
      this.fieldObservers.delete(key)
    }
  }
}
