  const typeGuid = typeScope?.guid ?? id;
  const store = useTypeStore(identitySelector, typeGuid ?? undefined);
  const syncedValue = useSyncOptional<Type, T>(store as TypeStore | null, selector ? selector : (identitySelector as any));
  return syncedValue;
