### **8. SketchpadScopeProvider** ([compose/sketchpad/sketchpad/Sketchpad.tsx](compose/sketchpad/sketchpad/Sketchpad.tsx#L13640))

**Provider Component (Lines 13640-13694)**:
```typescript
export const SketchpadScopeProvider = (props: {
  id?: string;
  store?: SketchpadStore;
  remote?: RemoteProviders;
  persistenceFactory?: PersistenceFactory;
  onWindowEvents?: WindowEvents;
  initialState?: ExtendedInitialState;
  importKitUrls?: string[];
  children: React.ReactNode;
}) => {
  const id = useMemo(() => props.id || guid(), [props.id]);

  // Create store if not provided
  if (!stores.has(id)) {
    const store = props.store ?? new SketchpadStore(
      id, 
      props?.remote, 
      props?.initialState, 
      props?.persistenceFactory
    );
    stores.set(id, store);

    const actor = createSketchpadActor({...});
    actor.start();
    actors.set(id, actor);
    store.setActor(actor);

    // Expose to window
    if (typeof window !== "undefined") {
      (window as any).__COMPOSE_STORE__ = store;
      (window as any).__COMPOSE_ACTOR__ = actor;
    }
  }

  return React.createElement(
    SketchpadScopeContext.Provider, 
    { value: { id, remote: props.remote, onWindowEvents: props.onWindowEvents } },
    React.createElement(SketchpadActorContext.Provider, { value: actor }, 
      configsReady ? props.children : null
    )
  );
};
